<?php declare(strict_types=1); namespace App\Http\Controllers\Pmbm; use App\Enums\Pmbm\ApplicantStatus; use App\Http\Controllers\Controller; use App\Http\Requests\Pmbm\StoreApplicantRequest; use App\Models\AcademicYear; use App\Models\Pmbm\{PmbmApplicant,PmbmDocumentRequirement,PmbmInterviewQuestion}; use App\Services\Pmbm\{PmbmRegistrationService,PmbmWorkflowService}; use Illuminate\Http\{RedirectResponse,Request}; use Illuminate\View\View;
class ApplicantController extends Controller { public function index(Request $r):View{$q=PmbmApplicant::with('academicYear');if($r->filled('status'))$q->where('status',$r->input('status'));if($s=$r->string('search')->trim()->toString())$q->where(fn($x)=>$x->where('registration_number','like',"%$s%")->orWhere('full_name','like',"%$s%")->orWhere('nik','like',"%$s%"));return view('pmbm.admin.index',['applicants'=>$q->latest()->paginate(15)->withQueryString(),'statuses'=>ApplicantStatus::cases()]);} public function create():View{return view('pmbm.admin.form',['years'=>AcademicYear::orderByDesc('starts_at')->get(),'requirements'=>PmbmDocumentRequirement::where('is_active',true)->orderBy('sort_order')->get()]);} public function store(StoreApplicantRequest $r,PmbmRegistrationService $s):RedirectResponse{$a=$s->submit($r->validated(),'offline',$r->user());return redirect()->route('pmbm.applicants.show',$a)->with('status','Pendaftaran offline berhasil dibuat.');} public function edit(PmbmApplicant $applicant):View{return view('pmbm.admin.form',['applicant'=>$applicant,'years'=>AcademicYear::orderByDesc('starts_at')->get(),'requirements'=>PmbmDocumentRequirement::where('is_active',true)->orderBy('sort_order')->get()]);} public function update(StoreApplicantRequest $r,PmbmApplicant $applicant,PmbmRegistrationService $s):RedirectResponse{$s->update($applicant,$r->validated(),$r->user());return redirect()->route('pmbm.applicants.show',$applicant)->with('status','Data pendaftar diperbarui.');} public function show(Request $r,PmbmApplicant $applicant):View{$applicant->load(['documents.verifiedBy','histories','academicYear','student','fitting','interview.answers','observation','decision']);$sensitive=$r->user()->can('pmbm.applicant.view-sensitive');return view('pmbm.admin.show',['applicant'=>$applicant,'sensitive'=>$sensitive,'questions'=>PmbmInterviewQuestion::where('active',true)->orderBy('sort_order')->get()]);} public function verify(Request $r,PmbmApplicant $applicant,PmbmRegistrationService $s):RedirectResponse{$r->validate(['note'=>'nullable|string|max:1000']);$s->finalizeVerification($applicant,$r->user(),$r->input('note'));return back()->with('status','Seluruh berkas wajib dinyatakan terverifikasi.');} public function verifyDocument(Request $r,PmbmApplicant $applicant,\App\Models\Pmbm\PmbmApplicantDocument $document,PmbmRegistrationService $s):RedirectResponse{$d=$r->validate(['status'=>'required|in:valid,invalid,revision_required','note'=>'nullable|string|max:1000']);$s->verifyDocument($applicant,$document,$d['status'],$d['note']??null,$r->user());return back()->with('status','Status dokumen diperbarui.');} public function markDecisionPending(Request $r,PmbmApplicant $applicant,PmbmRegistrationService $s):RedirectResponse{$s->markDecisionPending($applicant,$r->user());return back()->with('status','Pendaftar siap ditetapkan hasilnya.');} public function decide(Request $r,PmbmApplicant $applicant,PmbmWorkflowService $s):RedirectResponse{$d=$r->validate(['decision'=>'required|in:accepted,waitlisted,rejected','public_note'=>'nullable|string|max:1000','internal_note'=>'nullable|string|max:1000']);$s->recommendDecision($applicant,$d,$r->user());return back()->with('status','Rekomendasi keputusan PMBM disimpan.');}
public function scheduleFitting(Request $r,PmbmApplicant $applicant,PmbmWorkflowService $s):RedirectResponse{$d=$r->validate(['scheduled_at'=>'required|date','location'=>'nullable|string|max:255']);$s->scheduleFitting($applicant,$d,$r->user());return back()->with('status','Fitting dijadwalkan.');}
public function completeFitting(Request $r,PmbmApplicant $applicant,PmbmWorkflowService $s):RedirectResponse{$d=$r->validate(['shirt_size'=>'nullable|string|max:20','pants_size'=>'nullable|string|max:20','skirt_size'=>'nullable|string|max:20','hijab_size'=>'nullable|string|max:20','cap_size'=>'nullable|string|max:20','socks_size'=>'nullable|string|max:20','notes'=>'nullable|string|max:2000']);$s->completeFitting($applicant,$d,$r->user());return back()->with('status','Fitting diselesaikan.');}
public function scheduleInterview(Request $r,PmbmApplicant $applicant,PmbmWorkflowService $s):RedirectResponse{$d=$r->validate(['scheduled_at'=>'required|date']);$s->scheduleInterview($applicant,$d,$r->user());return back()->with('status','Wawancara dijadwalkan.');}
public function completeInterview(Request $r,PmbmApplicant $applicant,PmbmWorkflowService $s):RedirectResponse{$d=$r->validate(['summary'=>'nullable|string|max:2000','public_note'=>'nullable|string|max:1000','internal_note'=>'nullable|string|max:2000','answers'=>'array','answers.*'=>'nullable']);$s->completeInterview($applicant,$d,$r->user());return back()->with('status','Wawancara diselesaikan.');}
public function completeObservation(Request $r,PmbmApplicant $applicant,PmbmWorkflowService $s):RedirectResponse{$d=$r->validate(['result'=>'required|in:READY,NEEDS_SUPPORT,FOLLOW_UP_REQUIRED','summary'=>'nullable|string|max:2000','internal_note'=>'nullable|string|max:2000']);$s->completeObservation($applicant,$d,$r->user());return back()->with('status','Observasi diselesaikan.');}
public function approveDecision(PmbmApplicant $applicant,PmbmWorkflowService $s,Request $r):RedirectResponse{$s->approveDecision($applicant,$r->user());return back()->with('status','Keputusan disetujui.');}
public function promoteWaitlist(Request $r,PmbmApplicant $applicant,PmbmWorkflowService $s):RedirectResponse{$d=$r->validate(['promotion_reason'=>'required|string|max:1000']);$s->promoteWaitlist($applicant,$d['promotion_reason'],$r->user());return back()->with('status','Pendaftar cadangan dipromosikan.');} public function enroll(Request $r,PmbmApplicant $applicant,PmbmRegistrationService $s):RedirectResponse{$student=$s->enroll($applicant,$r->user());return redirect()->route('students.show',$student)->with('status','Calon murid berhasil dikonversi menjadi siswa.');} }
